package com.example.lending.domain;

import java.time.LocalDate;
import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;

    private Book(UUID id, String title, BookStatus status) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    public Loan loanTo(UUID memberId, LocalDate loanedAt) {
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        Loan loan = Loan.start(id, memberId, loanedAt);
        status = BookStatus.ON_LOAN;
        return loan;
    }

    // 반납 처리 자체는 Loan.returnBook이 맡는다. 여기서는 대출 중인 책만 다시 대출 가능 상태로 바꾼다.
    public void returnBook() {
        if (status != BookStatus.ON_LOAN) {
            throw new IllegalStateException("book is not on loan: " + id);
        }
        status = BookStatus.AVAILABLE;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    private final UUID id;
    private final String name;

    private Member(UUID id, String name) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
    }

    public static Member register(String name) {
        return new Member(UUID.randomUUID(), name);
    }

    public static Member reconstitute(UUID id, String name) {
        return new Member(id, name);
    }

    public void checkCanBorrow(long activeLoanCount) {
        if (activeLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void registered_member_can_be_fetched_by_id() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.name").value("김민지"))
                .andReturn().getResponse().getContentAsString();
        String memberId = objectMapper.readTree(registered).get("memberId").asText();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.name").value("김민지"));
    }

    @Test
    void registering_member_with_blank_name_returns_400() throws Exception {
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"   \"}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void fetching_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }
}
