package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        String memberId = registerMember();
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(book.get("id").asText(), memberId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(book.get("id").asText()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void member_cannot_borrow_more_than_five_books_at_once() throws Exception {
        String memberId = registerMember();

        for (int i = 0; i < 5; i++) {
            String bookId = registerBook("책 " + i);
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanJson(bookId, memberId)))
                    .andExpect(status().isCreated());
        }

        String sixthBookId = registerBook("여섯 번째 책");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(sixthBookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook("미등록 회원 대출");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, UUID.randomUUID().toString())))
                .andExpect(status().isNotFound());
    }

    @Test
    void returned_book_can_be_loaned_again() throws Exception {
        String bookId = registerBook("반납 후 재대출");
        String memberId = registerMember();
        String loanId = loanAndGetLoanId(bookId, memberId);

        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String bookId = registerBook("이중 반납");
        String memberId = registerMember();
        String loanId = loanAndGetLoanId(bookId, memberId);

        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returned_loans_do_not_count_toward_the_five_book_limit() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loanAndGetLoanId(registerBook("반납 한도 0"), memberId);
        for (int i = 1; i < 5; i++) {
            loanAndGetLoanId(registerBook("반납 한도 " + i), memberId);
        }

        mockMvc.perform(post("/loans/" + firstLoanId + "/return")).andExpect(status().isOk());

        String sixthBookId = registerBook("반납 후 여섯 번째 책");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(sixthBookId, memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/" + UUID.randomUUID() + "/return"))
                .andExpect(status().isNotFound());
    }

    @Test
    void loan_with_past_loanedAt_is_due_fourteen_days_later() throws Exception {
        String bookId = registerBook("과거 대출");
        String memberId = registerMember();

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJsonWithDate(bookId, memberId, "2026-01-01")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value("2026-01-01"))
                .andExpect(jsonPath("$.dueAt").value("2026-01-15"));
    }

    @Test
    void returning_on_due_date_has_no_late_fee() throws Exception {
        String loanId = loanWithDate(registerBook("기한 당일 반납"), registerMember(), "2026-01-01");

        returnWithDate(loanId, "2026-01-15")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_late_charges_100() throws Exception {
        String loanId = loanWithDate(registerBook("하루 연체"), registerMember(), "2026-01-01");

        returnWithDate(loanId, "2026-01-16")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_late_charges_500() throws Exception {
        String loanId = loanWithDate(registerBook("닷새 연체"), registerMember(), "2026-01-01");

        returnWithDate(loanId, "2026-01-20")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_body_uses_today_as_returnedAt() throws Exception {
        String loanId = loanAndGetLoanId(registerBook("본문 없는 반납"), registerMember());

        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_before_loanedAt_returns_400() throws Exception {
        String loanId = loanWithDate(registerBook("반납일이 대출일보다 이른 경우"), registerMember(), "2026-01-01");

        returnWithDate(loanId, "2025-12-31")
                .andExpect(status().isBadRequest());
    }

    private String loanWithDate(String bookId, String memberId, String loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJsonWithDate(bookId, memberId, loanedAt)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private ResultActions returnWithDate(String loanId, String returnedAt)
            throws Exception {
        return mockMvc.perform(post("/loans/" + loanId + "/return").contentType(MediaType.APPLICATION_JSON)
                .content("{\"returnedAt\":\"" + returnedAt + "\"}"));
    }

    private String loanJsonWithDate(String bookId, String memberId, String loanedAt) {
        return "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
    }

    private String loanAndGetLoanId(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"대출자\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String loanJson(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record LoanBody(String bookId, String memberId) {
    }
}

