    @Test
    void member_loans_list_only_active_loans_with_paging_and_total_count() throws Exception {
        String memberId = registerMember();
        loanWithDate(registerBook("회원 대출 목록 A"), memberId, "2026-02-01");
        String returnedLoanId = loanWithDate(registerBook("회원 대출 목록 B"), memberId, "2026-02-02");
        loanWithDate(registerBook("회원 대출 목록 C"), memberId, "2026-02-03");
        returnWithDate(returnedLoanId, "2026-02-05").andExpect(status().isOk());

        mockMvc.perform(get("/members/" + memberId + "/loans").param("page", "0").param("size", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("회원 대출 목록 A"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-01"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-15"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(1))
                .andExpect(jsonPath("$.totalCount").value(2));

        mockMvc.perform(get("/members/" + memberId + "/loans").param("page", "1").param("size", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("회원 대출 목록 C"))
                .andExpect(jsonPath("$.totalCount").value(2));
    }

